def purge_note_and_clear_backlinks(db, note_id):
    token = f"[[{note_id}]]"
    linked = db.execute(
        "SELECT id, body FROM notes WHERE body LIKE ?", (f"%{token}%",)
    ).fetchall()
    for other_id, body in linked:
        db.execute(
            "UPDATE notes SET body = ? WHERE id = ?",
            (body.replace(token, ""), other_id),
        )
    db.execute("DELETE FROM notes WHERE id = ?", (note_id,))
    db.commit()
    return len(linked)
